entries.search:
version Read the upstream node version. {
  "jsonrpc": "2.0",
  "method": "version",
  "params": {},
  "id": 1
} {
  "result": {
    "build_info": "<string>",
    "network": "<string>",
    "network_identifier": "<string>",
    "node_vendor": "<string>",
    "protocol_version": "<string>",
    "rpc_version": "<string>",
    "store_vendor": "<string>",
    "store_version": "<string>"
  }
}

block_count Read upstream ledger block counts. {
  "jsonrpc": "2.0",
  "method": "block_count",
  "params": {},
  "id": 1
} {
  "result": {
    "cemented": "<string>",
    "count": "<string>",
    "unchecked": "<string>"
  }
}

receivable Read receivable blocks for an account. {
  "jsonrpc": "2.0",
  "method": "receivable",
  "params": {
    "account": "<account>"
  },
  "id": 1
} {
  "result": {
    "blocks": "<array | object | object>"
  }
}

account_balance Read balance and receivable state for one account. {
  "jsonrpc": "2.0",
  "method": "account_balance",
  "params": {
    "account": "<account>"
  },
  "id": 1
} {
  "result": {
    "balance": "<string>",
    "receivable": "<string>"
  }
}

accounts_balances Read balances and receivables for several accounts. {
  "jsonrpc": "2.0",
  "method": "accounts_balances",
  "params": {
    "accounts": [
      "<account>"
    ]
  },
  "id": 1
} {
  "result": {
    "balances": {
      "<key>": {
        "balance": "<string>",
        "receivable": "<string>"
      }
    },
    "errors": {
      "<key>": "<string>"
    }
  }
}

block_info Read block metadata and whether the block is cemented. {
  "jsonrpc": "2.0",
  "method": "block_info",
  "params": {
    "hash": "<hash>"
  },
  "id": 1
} {
  "result": {
    "amount": "<string>",
    "balance": "<string>",
    "block_account": "<string>",
    "confirmed": "<string>",
    "contents": "<value>",
    "height": "<string>",
    "linked_account": "<string>",
    "local_timestamp": "<string>",
    "receive_hash": "<string>",
    "source_account": "<string>",
    "subtype": "<string>",
    "successor": "<string>"
  }
}

blocks_info Read metadata for several blocks. {
  "jsonrpc": "2.0",
  "method": "blocks_info",
  "params": {
    "hashes": [
      "<hash>"
    ]
  },
  "id": 1
} {
  "result": {
    "blocks": {
      "<key>": {
        "amount": "<string>",
        "balance": "<string>",
        "block_account": "<string>",
        "confirmed": "<string>",
        "contents": "<value>",
        "height": "<string>",
        "linked_account": "<string>",
        "local_timestamp": "<string>",
        "receive_hash": "<string>",
        "source_account": "<string>",
        "subtype": "<string>",
        "successor": "<string>"
      }
    },
    "blocks_not_found": [
      "<string>"
    ]
  }
}

accounts_frontiers Read the head block hash for each account. {
  "jsonrpc": "2.0",
  "method": "accounts_frontiers",
  "params": {
    "accounts": [
      "<account>"
    ]
  },
  "id": 1
} {
  "result": {
    "errors": {
      "<key>": "<string>"
    },
    "frontiers": {
      "<key>": "<string>"
    }
  }
}

accounts_receivable Read receivable blocks for several accounts. {
  "jsonrpc": "2.0",
  "method": "accounts_receivable",
  "params": {
    "accounts": [
      "<account>"
    ]
  },
  "id": 1
} {
  "result": {
    "blocks": {
      "<key>": "<array | object | object>"
    }
  }
}

block_confirm Request confirmation for a block from online representatives. {
  "jsonrpc": "2.0",
  "method": "block_confirm",
  "params": {
    "hash": "<hash>"
  },
  "id": 1
} {
  "result": {
    "started": "<string>"
  }
}

process Submit a precomputed block and return its hash. {
  "jsonrpc": "2.0",
  "method": "process",
  "params": {
    "block": "<block>"
  },
  "id": 1
} {
  "result": "<object | object>"
}
